struct ControlWord {
    // Width specified after colon
    unsigned int start : 1;
    unsigned int mode : 3;

    // Unnamed field for padding/reserved space
    unsigned int reserved : 4;

    // Unnamed field only for padding (4 bits unused)
    unsigned int : 4; 

    // Zero-width field forces subsequent field 
    // to start at the beginning of a new allocation unit (e.g., new int).
    unsigned int : 0;

    // New storage unit begins here
    int data_id : 12;

    // Base types determine the unit size (int, unsigned int, etc.)
    bool parity : 1; 
};

// Layout and sizeof() are implementation-defined (compiler/ABI specific).
